function findUser(uid){
  if(!uid) return null;
  var search = uid.toString().replace(/^@/,'').toLowerCase().trim();
  var found = null;
  // Cerca per numero lista: #1, #2, ecc.
  if(uid.toString().trim().charAt(0)==='#'){
    var listN = parseInt(uid.toString().trim().substring(1));
    var count = 0;
    for(var i=1;i<rows.length;i++){
      if(!rows[i]||!rows[i][0]) continue;
      count++;
      if(count===listN){ found={row:rows[i],index:i+1}; break; }
    }
    return found;
  }
  for(var i=1;i<rows.length;i++){
    if(!rows[i]||!rows[i][0]) continue;
    // ID numerico (colonna A)
    if(rows[i][0].toString()===search){ found={row:rows[i],index:i+1}; break; }
    // Username (colonna K, indice 10)
    var rowUser=(rows[i][10]||'').toString().replace(/^@/,'').toLowerCase();
    if(rowUser && rowUser===search){ found={row:rows[i],index:i+1}; break; }
    // Nome completo (case insensitive)
    var fullN=((rows[i][1]||'')+' '+(rows[i][2]||'')).trim().toLowerCase();
    if(fullN && fullN===search){ found={row:rows[i],index:i+1}; break; }
  }
  return found;
}
function escapeMd(s) {
    return (s || '').toString()
        .replace(/\\/g, '\\\\')
        .replace(/_/g, '\\_')
        .replace(/\*/g, '\\*')
        .replace(/\[/g, '\\[')
        .replace(/`/g, '\\`');
}

