var chatId = msg.payload.chatId;
var content = msg.payload.content || '';
var param = content.replace('/start', '').trim();

// out: [infogratis, fallback a start normale, comefunziona, metodo, bilancio, book, assistenza]
var out = [null, null, null, null, null, null, null];

if (param === 'infogratis') {
    // Arriva dal vecchio link di fallback del gruppo free: NON mostrare il benvenuto VIP
    out[0] = {payload: {chatId: chatId, type: 'message',
        content: '✅ Fatto! Ora torna nel gruppo e premi di nuovo il pulsante che avevi scelto: riceverai subito l\'informazione qui in privato.',
        options: {}}};
} else if (param === 'comefunziona') {
    out[2] = msg;
} else if (param === 'metodo') {
    out[3] = msg;
} else if (param === 'bilancio') {
    out[4] = msg;
} else if (param === 'book') {
    out[5] = msg;
} else if (param === 'assistenza') {
    out[6] = msg;
} else {
    // Parametro sconosciuto/assente: comportati come uno start normale
    out[1] = msg;
}
return out;

// Invio diretto via API Telegram (invece del sender condiviso) per poter
// leggere il message_id dalla risposta e usarlo per il pin automatico.
var BOT_TOKEN = env.get('BOT_TOKEN');
var p = msg.payload;
var opts = p.options || {};
var params = {
    chat_id: p.chatId,
    text: p.content,
    parse_mode: opts.parse_mode || 'Markdown',
    reply_markup: JSON.stringify(opts.reply_markup || {})
};
var qs = Object.keys(params).map(function(k){
    return k + '=' + encodeURIComponent(params[k]);
}).join('&');
msg.url = 'https://api.telegram.org/bot' + BOT_TOKEN + '/sendMessage?' + qs;
msg.method = 'GET';
return msg;

var result = msg.payload;
